package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/** Actual archive/hash metadata reads. Native input birth is a fictional fixture, not execution authority. */
@EnabledIfEnvironmentVariable(named="B45_MYSQL",matches="true")
class OwnerJobInputMetadataMySqlTest {
    OwnerJobViewsMySqlTest f;OwnerJobInputMetadataService service;JdbcFrozenInputs inputs;JsonNode body;
    final String root="fictional-metadata-root",intent="fictional-metadata-intent";
    final Instant cutoff=Instant.parse("2026-01-04T21:00:00Z");
    @BeforeEach void setup(){f=new OwnerJobViewsMySqlTest();f.setup();f.f.jdbc.update("DELETE FROM jobs");inputs=new JdbcFrozenInputs(f.f.source);service=new OwnerJobInputMetadataService(f.store,inputs);}
    void save(JsonNode snapshot){
        body=snapshot;String type=body.get("stage").asText();long generation=body.get("generation").asLong();String logical=body.get("logical_key").asText();var stage=GenerationFlowService.Stage.valueOf(type.toUpperCase(Locale.ROOT));
        f.writer.execute(s->{var records=new JdbcJobRecords(f.f.source);records.ensureIntent(new JdbcJobRecords.Intent(intent,logical,generation,type,LocalDate.parse(body.get("business_date").asText())),cutoff);records.createRoot(new JdbcJobRecords.Root(root,intent,logical,generation,0,type,stage.priority()),cutoff);
            String raw=JdbcFrozenInputs.canonical(body),hash=CanonicalJson.hash(CanonicalJson.Domain.INPUT,body);inputs.save(root,raw,hash,cutoff);f.f.jdbc.update(connection->{var statement=connection.prepareStatement("UPDATE jobs SET input_state='ready',coverage_state=?,missing_inputs_json=?,input_cutoff_at=? WHERE id=?");statement.setString(1,body.get("coverage_state").asText());statement.setString(2,JdbcFrozenInputs.canonical(body.get("missing")));statement.setTimestamp(3,java.sql.Timestamp.from(cutoff),Calendar.getInstance(TimeZone.getTimeZone("UTC")));statement.setString(4,root);return statement;});return true;});
    }
    JsonNode generic(){var node=JsonMapper.shared().createObjectNode().put("schema_version","1").put("logical_key","fictional-metadata-key").put("generation",1).put("stage","ad_hoc_ai").put("business_date","2026-01-04").put("cutoff","2026-01-04T21:00:00.000000Z").put("coverage_state","partial");node.putArray("missing").add("fictional-dependency");node.putArray("members").addObject().put("body_text","Fictional body sentinel retained in INPUT only");return node;}
    JsonNode report(){var command=ReportInputSnapshotServiceTest.command(GenerationFlowService.Stage.WEEKLY_REPORT,LocalDate.of(2026,1,4));var frozen=ReportInputSnapshotServiceTest.freeze(command,cutoff,List.of(),List.of(LocalDate.of(2025,12,29)));var node=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(frozen.snapshotJson());var context=node.putObject(FrozenApplicationContext.FIELD).put("schema_version","frozen-application-context-v1").put("stage","weekly_report").put("generation",2).putNull("target_entity_id").put("period_start","2025-12-28T16:00:00.000000Z").put("period_end","2026-01-04T16:00:00.000000Z").put("references_complete",true);context.putObject("target_content").put("kind","report").put("id","fictional-report-content").putNull("base_revision");for(String field:List.of("item_ids","eligible_high_value_item_ids","allowed_citation_ids","version_eligible_item_ids","reference_targets","candidates_by_item"))context.putArray(field);return node;}
    @Test void actualGenericInputHashProducesOnlySnapshotAndCoverageMetadata(){save(generic());var metadata=f.read(()->service.read(root));assertEquals(root,metadata.inputSnapshotId());assertNull(metadata.contentId());assertEquals("partial",metadata.coverage().state());assertEquals("fictional-dependency",metadata.coverage().missingInputs().getFirst().id());assertTrue(metadata.inputBytes()>0);assertFalse(metadata.toString().contains("body sentinel"));assertEquals(0,f.f.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));}
    @Test void actualOriginalReportRetainsItsContentTargetMissingAndNoUpdateDates(){save(report());var metadata=f.read(()->service.read(root));assertEquals("fictional-report-content",metadata.contentId());assertEquals(List.of(LocalDate.of(2025,12,29)),metadata.coverage().noUpdateDates());assertEquals(6,metadata.coverage().missingDates().size());assertFalse(metadata.coverage().missingDates().contains(LocalDate.of(2025,12,29)));assertEquals(body.get("coverage_state").asText(),metadata.coverage().state());}
    @Test void nativeArchiveHashCutoffCoverageOrMissingDamageIsNeverAnEmptyProof(){save(generic());f.f.jdbc.update("UPDATE jobs SET payload_hash=? WHERE record_kind='snapshot_part'",new byte[32]);assertThrows(RuntimeException.class,()->f.read(()->service.read(root)));setup();save(generic());f.f.jdbc.update("UPDATE jobs SET coverage_state='complete' WHERE id=?",root);assertThrows(RuntimeException.class,()->f.read(()->service.read(root)));setup();save(generic());f.f.jdbc.update("UPDATE jobs SET missing_inputs_json='[]' WHERE id=?",root);assertThrows(RuntimeException.class,()->f.read(()->service.read(root)));setup();save(generic());f.f.jdbc.update("UPDATE jobs SET input_cutoff_at='2026-01-01 00:00:00' WHERE id=?",root);assertThrows(RuntimeException.class,()->f.read(()->service.read(root)));}
    @Test void missingReportProfileOrMalformedOriginalContextCannotSupplyInventedDatesOrTarget(){var report=generic();((tools.jackson.databind.node.ObjectNode)report).put("stage","daily_report");save(report);assertThrows(RuntimeException.class,()->f.read(()->service.read(root)));setup();var bad=report();((tools.jackson.databind.node.ObjectNode)bad.get(FrozenApplicationContext.FIELD)).put("generation",3);save(bad);assertThrows(RuntimeException.class,()->f.read(()->service.read(root)));}
    @Test void absentInputDiffersFromOrphanChunksAndWrongTransactionOrRole(){f.writer.execute(s->{new JdbcJobRecords(f.f.source).ensureIntent(new JdbcJobRecords.Intent(intent,"fictional-key",1,"ad_hoc_ai",LocalDate.of(2026,1,4)),cutoff);new JdbcJobRecords(f.f.source).createRoot(new JdbcJobRecords.Root(root,intent,"fictional-key",1,0,"ad_hoc_ai",14),cutoff);return true;});assertNull(f.read(()->service.read(root)));assertThrows(RuntimeException.class,()->service.read(root));assertThrows(RuntimeException.class,()->f.writer.execute(s->service.read(root)));assertThrows(RuntimeException.class,()->f.read(()->service.read(intent)));setup();save(generic());f.f.jdbc.update("UPDATE jobs SET input_snapshot_json=NULL,input_hash=NULL WHERE id=?",root);assertThrows(RuntimeException.class,()->f.read(()->service.read(root)));}
    @Test void boundedNativeInputReferencesAndIntentRootsDoNotLoadOversizedBody(){save(generic());var nativeInput=f.read(()->f.store.inputReference(root));assertTrue(nativeInput.present());assertEquals(1,nativeInput.parts());assertEquals(1,f.read(()->f.store.roots(intent)).size());f.f.jdbc.update("UPDATE jobs SET payload_json=? WHERE record_kind='snapshot_part'","{\"fictional\":\""+"F".repeat(6400000)+"\"}");assertThrows(RuntimeException.class,()->f.read(()->f.store.inputReference(root)));assertThrows(RuntimeException.class,()->f.read(()->service.read(root)));}
}
